   const workspace=field(section,'百炼业务空间 ID（形如 llm-xxxx）',''),region=choiceField(section,'百炼地域',[['cn-beijing','北京'],['ap-southeast-1','新加坡']],'cn-beijing');
   const matched=(c.url||'').match(/^https:\/\/([a-zA-Z0-9-]+)\.(cn-beijing|ap-southeast-1)\.maas\.aliyuncs\.com\//);if(matched){workspace.value=matched[1];region.setChoice(matched[2]);}
  const makeUrl=()=>{if(workspace.value.trim())url.value='https://'+workspace.value.trim()+'.'+region.value+'.maas.aliyuncs.com/compatible-mode/v1';};workspace.oninput=makeUrl;region.onchange=makeUrl;
  select.onchange=()=>{const previous=provider;provider=select.value;if(provider==='jev'){if(previous!=='jev'){url.value='https://openrouter.ai/api/v1';model.value='typesafe/jev-1.13';key.value='';}}else if(provider==='bailian'){if(previous!=='bailian'){url.value='';model.value='decision-model-preview';key.value='';}makeUrl();}else if(previous!=='compatible'){url.value='';model.value='';key.value='';}};
  if(provider==='jev'&&!url.value)url.value='https://openrouter.ai/api/v1';if(provider==='bailian'&&!model.value)model.value='decision-model-preview';
  section.append(el('p','muted','百炼：填写业务空间 ID 和地域生成地址，使用该空间的密钥。Token Plan 可直接填 https://token-plan.cn-beijing.maas.aliyuncs.com/compatible-mode/v1 和对应密钥。模型填 decision-model-preview。'));
