 const background=group('后台计划与生成');background.body.append(el('p','notice','每天约03:00核对本地计划，并按后台检查间隔和任务到期时间再次核对；系统非精确唤醒，联网生成交给WorkManager，不要求WebView常驻。'));number(background.body,'historyLimit','最多参考历史消息（4–100 条）',4,100);number(background.body,'memoryLimit','最多引用记忆（0–20 条）',0,20);
 check(background.body,'notifications','主动消息系统通知');check(background.body,'privacy','系统通知隐藏消息正文');background.body.append(el('p','notice','断网时WorkManager等待网络，超过有效期就跳过。已发出的请求失败或中断后不自动重发；今日计划可手动重试，可能再次计费。增加上下文会增加费用。OriginOS冻结仍可能阻止执行，可在应用后台耗电设置中允许后台运行。'));
 const look=group('系统通知与提示');check(look.body,'sound','收到搭话时播放系统消息提示音');check(look.body,'vibrate','收到搭话时振动');look.body.append(el('p','notice','消息只通过系统通知提醒；已取消应用内及跨应用自绘弹窗。横幅位置、尺寸和停留时间由系统控制。'));const notificationBadge=el('p','notice',state.notificationsAllowed?'系统通知已允许':'系统通知未允许，应用内未读仍会保存');notificationBadge.dataset.reachNotificationStatus='';look.body.append(notificationBadge);
