 area.append(btn('保存搭话设置',async()=>{const args={enabled:enabled.checked,characters:allowed.filter(e=>e.input.checked).map(e=>e.id),characterLimits:{}};for(const e of allowed){if(e.limit.value.trim()){const n=e.limit.valueAsNumber;if(!Number.isInteger(n)||n<1||n>30)throw new Error(e.id+'的每日上限应为1到30');args.characterLimits[e.id]=n;}}for(const [key,n] of Object.entries(controls)){if(n.type==='number'){const value=n.valueAsNumber;if(!Number.isFinite(value)||value<Number(n.min)||value>Number(n.max)||n.step==='1'&&!Number.isInteger(value)){const section=n.closest('details');if(section)section.open=true;n.focus();throw new Error('请填写范围内的有效数值：'+n.previousSibling.textContent);}args[key]=value;}else args[key]=n.type==='checkbox'?n.checked:n.value;}for(const key of ['trust','close','intimate'])if(args[key+'Min']>args[key+'Max'])throw new Error('关系间隔的最短时间不能大于最长时间');if(args.quietStart===args.quietEnd)throw new Error('免打扰开始和结束不能相同；全天允许请关闭免打扰开关');state=await api('reachSettings',args);toast('已保存；分配规则有变化时才更新计划');render();},'pill primary wide'));
