let reachDismissTimer;
function showReach(message){
 clearTimeout(reachDismissTimer);document.querySelector('.reach-popup')?.remove();
 // Android owns message alerts. UI events only update messages and unread counts.
}

function chatDisplay(){
 const list=document.querySelector('#messages'),position=list?.scrollTop||0;
 modal.replaceChildren(el('h2','','聊天显示'));
 const check=(label,checked)=>{const row=el('label','check'),input=el('input');input.type='checkbox';input.checked=checked;row.append(input,document.createTextNode(label));modal.append(row);return input;};
 const japanese=check('显示日文原文',!state.hideJapanese),voice=check('显示消息小喇叭',!state.hideVoiceIcon),replyWaiting=check('显示等待回复提示',!state.hideReplyWaiting);
 modal.append(el('p','notice','设置会保存在这台手机。隐藏小喇叭后，中文补译按钮仍可使用。'),btn('保存',async()=>{state=await api('displaySettings',{hideJapanese:!japanese.checked,hideVoiceIcon:!voice.checked,hideReplyWaiting:!replyWaiting.checked});modal.close();render();requestAnimationFrame(()=>{const next=document.querySelector('#messages');if(next)next.scrollTop=position;});},'pill primary wide'),btn('取消',()=>modal.close(),'pill wide'));
 modal.showModal();
}

function storyRetrievalSettings(){
 header('剧情检索范围',true);const area=content(),o=state.storyRetrieval||{},fields=[];
 area.append(el('p','notice','控制聊天时的本地剧情检索，也用于进程中断后的后台恢复生成。先用关键词筛选当前角色相关剧情，再在候选范围内排序并引用。'));
 for(const [key,title,min,max,fallback,note] of [
  ['candidates','广度：最多评估的候选剧情条数',30,2000,120,'提高后能评估更多匹配剧情，也会增加本地检索耗时。'],
  ['terms','广度：最多使用的检索关键词数',8,64,24,'从本轮检索文本提取关键词；数量越多，匹配范围越广。'],
  ['passages','深度：最多引用的剧情段数',1,8,2,'提供给聊天模型的剧情数量上限，实际数量取决于匹配结果。'],
  ['chars','深度：每段最多提供的字数',300,6000,900,'围绕关键词截取剧情上下文；增加后模型可读到更多原文。']
 ]){const input=field(area,title,o[key]??fallback,'number');input.min=min;input.max=max;input.step=1;fields.push([key,input]);area.append(el('p','muted',note));}
 area.append(el('p','notice','默认：120 条候选、24 个关键词、2 段引用、每段 900 字。引用总量最多 24000 字。扩大范围不会额外调用判断模型；引用更多原文会增加聊天请求的上下文和费用。剧情检索总开关位于“记忆与关系设置”。保存后用于后续检索，已生成的待发送回复不会重新生成。'));
 area.append(btn('保存检索范围',async()=>{const options={};for(const [key,input] of fields){if(!input.checkValidity()){input.reportValidity();return;}options[key]=Number(input.value);}if(options.passages*options.chars>24000){toast('引用段数 × 每段字数不能超过 24000 字');return;}state=await api('storyRetrievalSettings',options);toast('剧情检索范围已保存');render();},'pill primary wide'));
}





